using System.Text.Json.Serialization;
namespace FuelMind.Desktop.Dtos.Operations;
public sealed class AttendantDto { [JsonPropertyName("id")] public int Id { get; init; } [JsonPropertyName("station_id")] public int StationId { get; init; } [JsonPropertyName("code")] public string Code { get; init; } = ""; [JsonPropertyName("full_name")] public string FullName { get; init; } = ""; [JsonPropertyName("employee_number")] public string EmployeeNumber { get; init; } = ""; [JsonPropertyName("phone")] public string? Phone { get; init; } [JsonPropertyName("is_active")] public bool IsActive { get; init; } }
public sealed class AttendantSaveDto { [JsonPropertyName("station_id")] public int StationId { get; init; } [JsonPropertyName("code")] public string Code { get; init; } = ""; [JsonPropertyName("full_name")] public string FullName { get; init; } = ""; [JsonPropertyName("employee_number")] public string EmployeeNumber { get; init; } = ""; [JsonPropertyName("phone")] public string? Phone { get; init; } [JsonPropertyName("is_active")] public bool IsActive { get; init; } = true; }
public sealed class ShiftDto { [JsonPropertyName("id")] public int Id { get; init; } [JsonPropertyName("station_id")] public int StationId { get; init; } [JsonPropertyName("code")] public string Code { get; init; } = ""; [JsonPropertyName("name")] public string Name { get; init; } = ""; [JsonPropertyName("start_time")] public TimeOnly StartTime { get; init; } [JsonPropertyName("end_time")] public TimeOnly EndTime { get; init; } [JsonPropertyName("is_active")] public bool IsActive { get; init; } public string Schedule => $"{StartTime:HH\\:mm} – {EndTime:HH\\:mm}"; }
public sealed class ShiftSaveDto { [JsonPropertyName("station_id")] public int StationId { get; init; } [JsonPropertyName("code")] public string Code { get; init; } = ""; [JsonPropertyName("name")] public string Name { get; init; } = ""; [JsonPropertyName("start_time")] public TimeOnly StartTime { get; init; } [JsonPropertyName("end_time")] public TimeOnly EndTime { get; init; } [JsonPropertyName("is_active")] public bool IsActive { get; init; } = true; }
public sealed class AssignmentSaveDto { [JsonPropertyName("attendant_id")] public int AttendantId { get; init; } [JsonPropertyName("shift_id")] public int ShiftId { get; init; } [JsonPropertyName("is_active")] public bool IsActive { get; init; } = true; }
public sealed class AssignmentDto { [JsonPropertyName("id")] public int Id { get; init; } [JsonPropertyName("attendant_id")] public int AttendantId { get; init; } [JsonPropertyName("shift_id")] public int ShiftId { get; init; } [JsonPropertyName("station_id")] public int StationId { get; init; } [JsonPropertyName("is_active")] public bool IsActive { get; init; } }
